
pub struct REncoder; impl REncoder { pub fn encode(data: &[u8]) -> Vec<u8> { let mut res = Vec::with_capacity(data.len()); let mut i = 0; while i < data.len() { if data[i] == 0xFE { res.push(0xFE); res.push(0x00); i += 1; continue; } if data[i] == 0 && i + 3 < data.len() { let mut c = 0; while i + c < data.len() && data[i+c] == 0 && c < 255 { c += 1; } if c >= 4 { res.push(0xFE); res.push(0x01); res.push(c as u8); i += c; continue; } } if i + 6 < data.len() && data[i] == data[i+2] && data[i] == data[i+4] && data[i+1] == data[i+3] && data[i+1] == data[i+5] && data[i] != data[i+1] { let (a, b) = (data[i], data[i+1]); let mut c = 0; while i + c2 + 1 < data.len() && data[i+c2] == a && data[i+c*2+1] == b && c < 255 { c += 1; } if c >= 3 { res.push(0xFE); res.push(0x02); res.push(a); res.push(b); res.push(c as u8); i += c * 2; continue; } } res.push(data[i]); i += 1; } res } pub fn decode(data: &[u8]) -> Vec<u8> { let mut res = Vec::new(); let mut i = 0; while i < data.len() { if data[i] == 0xFE && i + 1 < data.len() { match data[i+1] { 0x00 => { res.push(0xFE); i += 2; } 0x01 => { let c = data[i+2]; for _ in 0..c { res.push(0); } i += 3; } 0x02 => { let (a, b, c) = (data[i+2], data[i+3], data[i+4]); for _ in 0..c { res.push(a); res.push(b); } i += 5; } _ => { res.push(data[i]); i += 1; } } } else { res.push(data[i]); i += 1; } } res } }